import{_ as e,o as l,c as i,O as o}from"./chunks/framework.db831a78.js";const m=JSON.parse('{"title":"JVM","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/02-JVM.md","filePath":"interview/后端/Java/02-JVM.md","lastUpdated":null}'),r={name:"interview/后端/Java/02-JVM.md"};function t(c,a,d,h,n,s){return l(),i("div",null,a[0]||(a[0]=[o('<h1 id="jvm" tabindex="-1">JVM <a class="header-anchor" href="#jvm" aria-label="Permalink to &quot;JVM&quot;">​</a></h1><blockquote><p>常问等级：★★★ 高频必考 / ★★☆ 中频常见 / ★☆☆ 低频了解</p></blockquote><h2 id="jvm-内存区域划分-各区域作用-哪些会-oom-★★★" tabindex="-1">JVM 内存区域划分，各区域作用，哪些会 OOM ★★★ <a class="header-anchor" href="#jvm-内存区域划分-各区域作用-哪些会-oom-★★★" aria-label="Permalink to &quot;JVM 内存区域划分，各区域作用，哪些会 OOM ★★★&quot;">​</a></h2><ul><li>线程私有：程序计数器（当前执行位置，唯一不 OOM）、虚拟机栈（方法栈帧，StackOverflowError）、本地方法栈。</li><li>线程共享：堆（对象实例，OOM：Java heap space）、方法区/元空间（类元数据、常量、静态变量，OOM：Metaspace）、直接内存（NIO，OOM：Direct buffer memory）。</li></ul><h2 id="对象创建过程-对象内存布局-对象头-★★☆" tabindex="-1">对象创建过程，对象内存布局，对象头 ★★☆ <a class="header-anchor" href="#对象创建过程-对象内存布局-对象头-★★☆" aria-label="Permalink to &quot;对象创建过程，对象内存布局，对象头 ★★☆&quot;">​</a></h2><ul><li>创建：new → 检查类是否加载 → 分配内存（指针碰撞/空闲列表，取决于是否规整）→ 零值初始化 → 设置对象头 → 执行 <code>&lt;init&gt;</code>。</li><li>内存布局：对象头（Mark Word + 类型指针，数组还有长度）+ 实例数据 + 对齐填充（补齐 8 字节倍数）。</li><li>对象头 Mark Word 存储 hashCode、GC 分代年龄、锁状态标志、偏向锁线程 ID 等。</li></ul><h2 id="如何判断对象是垃圾-四种引用-★★★" tabindex="-1">如何判断对象是垃圾；四种引用 ★★★ <a class="header-anchor" href="#如何判断对象是垃圾-四种引用-★★★" aria-label="Permalink to &quot;如何判断对象是垃圾；四种引用 ★★★&quot;">​</a></h2><ul><li>可达性分析：从 GC Roots（栈引用、静态变量、常量等）出发，不可达即为垃圾。引用计数法有循环引用问题，主 JVM 不用。</li><li>引用：强引用（不回收）、软引用（OOM 前回收，做缓存）、弱引用（GC 即回收，如 WeakHashMap/ThreadLocal）、虚引用（仅用于回收跟踪，配合引用队列）。</li></ul><h2 id="gc-三大算法-★★★" tabindex="-1">GC 三大算法 ★★★ <a class="header-anchor" href="#gc-三大算法-★★★" aria-label="Permalink to &quot;GC 三大算法 ★★★&quot;">​</a></h2><ul><li>标记清除：标记存活、清除未标记，产生碎片。</li><li>复制：分两半，存活对象复制到另一半后清空，无碎片但浪费空间，用于新生代（Eden 8 : S0 1 : S1 1）。</li><li>标记整理：标记后存活对象向一端移动，无碎片但耗时，用于老年代。</li></ul><h2 id="常见垃圾收集器-★★★" tabindex="-1">常见垃圾收集器 ★★★ <a class="header-anchor" href="#常见垃圾收集器-★★★" aria-label="Permalink to &quot;常见垃圾收集器 ★★★&quot;">​</a></h2><ul><li>Serial/Serial Old：单线程，新生代复制/老年代标记整理，停顿大，客户端用。</li><li>Parallel Scavenge/Parallel Old：多线程，关注吞吐量，默认 JDK8 组合。</li><li>CMS：并发标记清除，追求低停顿；缺点：碎片、浮动垃圾、并发标记期间 CPU 高，已废弃（JDK9）。</li><li>G1：Region 分区 + 复制，可预测停顿模型（-XX:MaxGCPauseMillis），JDK9 默认。</li><li>ZGC：着色指针 + 读屏障，极低停顿（亚毫秒级），适合大堆，JDK15 量产。</li></ul><h2 id="类加载全过程-双亲委派模型-破坏双亲委派-★★★" tabindex="-1">类加载全过程；双亲委派模型；破坏双亲委派 ★★★ <a class="header-anchor" href="#类加载全过程-双亲委派模型-破坏双亲委派-★★★" aria-label="Permalink to &quot;类加载全过程；双亲委派模型；破坏双亲委派 ★★★&quot;">​</a></h2><ul><li>流程：加载 → 验证 → 准备（分配默认值）→ 解析 → 初始化（执行 clinit）。</li><li>双亲委派：加载请求先委托父加载器（Bootstrap → Extension → Application），父无法加载才自己加载；避免重复加载、保护核心类（防篡改 String）。</li><li>破坏场景：Tomcat 各 Web 应用类隔离（WebAppClassLoader 先自行加载）、JDBC SPI（线程上下文类加载器）、OSGi 热部署。</li></ul><h2 id="oom-常见场景-jmap、jstack-工具作用-★★★" tabindex="-1">OOM 常见场景；jmap、jstack 工具作用 ★★★ <a class="header-anchor" href="#oom-常见场景-jmap、jstack-工具作用-★★★" aria-label="Permalink to &quot;OOM 常见场景；jmap、jstack 工具作用 ★★★&quot;">​</a></h2><ul><li>场景：堆溢出（对象过多/大对象）、栈溢出（递归过深）、元空间溢出（动态生成类过多）、GC overhead limit exceeded。</li><li>jmap：查看堆快照（-dump 生成 hprof），配合 MAT 分析；jstack：打印线程栈、检测死锁、定位 CPU 高线程；jstat 看 GC 状态；jinfo 查看/调整参数。</li></ul><h2 id="逃逸分析-栈上分配-★★☆" tabindex="-1">逃逸分析，栈上分配 ★★☆ <a class="header-anchor" href="#逃逸分析-栈上分配-★★☆" aria-label="Permalink to &quot;逃逸分析，栈上分配 ★★☆&quot;">​</a></h2><ul><li>逃逸分析：分析对象是否逃出方法/线程作用域；不逃逸则可能栈上分配、标量替换、同步消除。</li><li>栈上分配对象随栈帧销毁，减轻 GC 压力（-XX:+DoEscapeAnalysis 默认开启）。</li></ul><h2 id="jvm-常用调优参数-★★☆" tabindex="-1">JVM 常用调优参数 ★★☆ <a class="header-anchor" href="#jvm-常用调优参数-★★☆" aria-label="Permalink to &quot;JVM 常用调优参数 ★★☆&quot;">​</a></h2><ul><li>堆：<code>-Xms</code>（初始）<code>-Xmx</code>（最大）<code>-Xmn</code>（新生代）；栈 <code>-Xss</code>。</li><li>元空间：<code>-XX:MetaspaceSize</code>、<code>-XX:MaxMetaspaceSize</code>。</li><li>GC 日志：<code>-Xlog:gc*</code>；导出 OOM 快照 <code>-XX:+HeapDumpOnOutOfMemoryError -XX:HeapDumpPath=...</code>。</li></ul><h2 id="jmm-与-jvm-内存模型的区别-★★★" tabindex="-1">JMM 与 JVM 内存模型的区别 ★★★ <a class="header-anchor" href="#jmm-与-jvm-内存模型的区别-★★★" aria-label="Permalink to &quot;JMM 与 JVM 内存模型的区别 ★★★&quot;">​</a></h2><ul><li>JVM 内存模型（内存区域）是「数据存储的物理划分」，分堆/栈/方法区等。</li><li>JMM（Java 内存模型）是「并发规范」，规定共享变量的可见性、有序性，抽象出主内存与工作内存，通过 volatile/final/synchronized/lock 建立 happens-before 规则。</li></ul><h2 id="元空间-vs-永久代、字符串常量池位置-★★☆" tabindex="-1">元空间 vs 永久代、字符串常量池位置 ★★☆ <a class="header-anchor" href="#元空间-vs-永久代、字符串常量池位置-★★☆" aria-label="Permalink to &quot;元空间 vs 永久代、字符串常量池位置 ★★☆&quot;">​</a></h2><ul><li>JDK7 起字符串常量池从永久代移到堆；JDK8 用元空间（本地内存）替代永久代，方法区逻辑概念保持一致。</li><li>好处：元空间不受 -XX:MaxPermSize 限制、由本机内存分配，避免永久代 OOM。</li></ul><h2 id="直接内存-★★☆" tabindex="-1">直接内存 ★★☆ <a class="header-anchor" href="#直接内存-★★☆" aria-label="Permalink to &quot;直接内存 ★★☆&quot;">​</a></h2><ul><li>NIO 通过 ByteBuffer.allocateDirect 分配堆外内存，避免 GC 和复制；但不受堆大小管控，满时触发 OOM（Direct buffer memory），-XX:MaxDirectMemorySize 控制。</li></ul><h2 id="三色标记、对象进入老年代条件、stw-★★☆" tabindex="-1">三色标记、对象进入老年代条件、STW ★★☆ <a class="header-anchor" href="#三色标记、对象进入老年代条件、stw-★★☆" aria-label="Permalink to &quot;三色标记、对象进入老年代条件、STW ★★☆&quot;">​</a></h2><ul><li>三色标记：并发标记的可达性算法，白（未访问）、灰（已访问子未扫）、黑（子已扫）；漏标需 SATB（G1）或增量更新（CMS）等写屏障补救。</li><li>进老年代：年龄达阈值（默认 15）、大对象直接进（-XX:PretenureSizeThreshold）、Survivor 空间不足、动态年龄判断。</li><li>STW：Stop The World，GC 时停止用户线程，追求低停顿即减少 STW。</li></ul>',28)]))}const M=e(r,[["render",t]]);export{m as __pageData,M as default};
